-- composition of rule kernels P:ProjectionPushdown x P:join_selection (datafusion), template not_exists
SELECT count(*) FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a2.c0, a2.c3 UNION ALL (SELECT '2024-01-01'::date AS c0 UNION SELECT '2024-01-01'::date AS c0)) AS ka WHERE NOT EXISTS (SELECT 1 FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a2.c3, a1.c0 UNION ALL (SELECT '2024-01-01'::date AS c0 UNION SELECT '2000-01-01'::date AS c0)) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a2.c3, a1.c0 UNION ALL (SELECT '2024-01-01'::date AS c0 UNION SELECT '2000-01-01'::date AS c0)) AS kb) = 0 THEN (SELECT count(*) FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a2.c0, a2.c3 UNION ALL (SELECT '2024-01-01'::date AS c0 UNION SELECT '2024-01-01'::date AS c0)) AS ka) ELSE 0 END
